CREATE DEFINER=`nrberp25`@`localhost` PROCEDURE `sp_CompleteServiceList` (IN `startDate` DATE, IN `endDate` DATE)   BEGIN
    WITH salesService AS (
        SELECT 
            psd.id as psd_id,
            ps.invoice_no AS invoice_no,
        	psd.service_invoice AS service_invoice,
            fa.account_name AS customer_name,
            p.product_name AS product_name,
            psd.service_date AS service_date,
            psd.actual_service_date AS actual_service_date,
            psd.service_number AS service_number,
            psd.service_status AS service_status,
            ps.done_by AS done_by
        FROM 
            product_services AS ps
        JOIN 
            product_service_details AS psd ON ps.id = psd.product_service_id
        JOIN 
            products AS p ON ps.product_id = p.id
        JOIN 
            finance_accounts AS fa ON ps.customer_id = fa.id
        WHERE 
            psd.service_status = 1
        AND
            psd.actual_service_date BETWEEN startDate AND endDate
    )
    SELECT 
        psd_id,
        invoice_no,
        service_invoice,
        customer_name,
        product_name,
        service_date,
        actual_service_date,
        service_number,
        service_status,
        done_by
    FROM 
        salesService
    ORDER BY 
        actual_service_date;
END$$

CREATE DEFINER=`nrberp25`@`localhost` PROCEDURE `sp_DamageProductDateWise` (IN `CDate1` DATE, IN `CDate2` DATE, IN `CWarehouseId` INT, IN `CProductId` INT)   BEGIN
    SELECT 
        dp.id, 
        dp.damage_no, 
        p.product_name, 
        w.name, 
        fa.account_name as supplier_name,
        fa2.account_name as customer_name,
        dp.purchasePrice, 
        dp.salePrice, 
        dp.damage_quantity, 
        dp.damage_reason, 
        dp.damage_date, 
        dp.is_exchangeable, 
        dp.is_repairable, 
        dp.is_resaleable, 
        dp.status, 
        dp.done_by, 
        dp.created_at, 
        dp.updated_at
    FROM 
        damage_products dp
    LEFT JOIN 
        products p ON dp.product_id = p.id
    LEFT JOIN 
        warehouses w ON dp.warehouse_id = w.id
    LEFT JOIN 
        finance_accounts fa ON dp.supplier_id = fa.id
    LEFT JOIN 
        finance_accounts fa2 ON dp.customer_id = fa2.id
    WHERE 
        dp.damage_date BETWEEN CDate1 AND CDate2
        AND (dp.warehouse_id = CWarehouseId OR CWarehouseId IS NULL)
        AND (dp.product_id = CProductId OR CProductId IS NULL);
END$$

CREATE DEFINER=`nrberp25`@`localhost` PROCEDURE `sp_GeneralLedgerByAccount` (IN `ACCID` INT, IN `CDate1` DATE, IN `CDate2` DATE, IN `PDate1` DATE, IN `PDate2` DATE)   BEGIN

SELECT
    `date`,
    company_code,
    voucher_no,
    to_acc_name,
    amount,
    balance_type,
    narration,
    cheque_no,
    cheque_date,
    cheque_type,
    type
FROM
(
    /* ===================== Opening Balance ===================== */
    SELECT
        0 AS sort_order,
        PDate2 AS sort_date,

        '' AS `date`,
        company_code,
        '' AS voucher_no,
        '' AS to_acc_name,

        CASE
            WHEN (
                COALESCE(
                    SUM(CASE WHEN balance_type = 'Dr' THEN amount ELSE 0 END) -
                    SUM(CASE WHEN balance_type = 'Cr' THEN amount ELSE 0 END),
                    0
                ) < 0
            )
            THEN ABS(
                COALESCE(
                    SUM(CASE WHEN balance_type = 'Dr' THEN amount ELSE 0 END) -
                    SUM(CASE WHEN balance_type = 'Cr' THEN amount ELSE 0 END),
                    0
                )
            )
            ELSE
                COALESCE(
                    SUM(CASE WHEN balance_type = 'Dr' THEN amount ELSE 0 END) -
                    SUM(CASE WHEN balance_type = 'Cr' THEN amount ELSE 0 END),
                    0
                )
        END AS amount,

        CASE
            WHEN (
                COALESCE(
                    SUM(CASE WHEN balance_type = 'Dr' THEN amount ELSE 0 END) -
                    SUM(CASE WHEN balance_type = 'Cr' THEN amount ELSE 0 END),
                    0
                ) < 0
            )
            THEN 'Cr'
            ELSE 'Dr'
        END AS balance_type,

        CONCAT(
            'Opening Balance as on : ',
            DATE_FORMAT(PDate2, '%d-%m-%Y')
        ) AS narration,

        '' AS cheque_no,
        '' AS cheque_date,
        '' AS cheque_type,
        '' AS type

    FROM finance_transactions
    WHERE acid = ACCID
      AND voucher_date BETWEEN PDate1 AND PDate2
    GROUP BY company_code

    UNION ALL

    /* ===================== Transaction List ===================== */
    SELECT
        1 AS sort_order,
        voucher_date AS sort_date,

        DATE_FORMAT(voucher_date, '%d-%m-%Y') AS `date`,
        company_code,
        voucher_no,
        to_acc_name,
        amount,
        balance_type,
        narration,
        cheque_no,

        CASE
            WHEN cheque_date = '0001-01-01' THEN ''
            ELSE DATE_FORMAT(cheque_date, '%d-%m-%Y')
        END AS cheque_date,

        cheque_type,
        type

    FROM finance_transactions
    WHERE acid = ACCID
      AND voucher_date BETWEEN CDate1 AND CDate2

) AS LedgerReport

ORDER BY
    sort_order ASC,
    sort_date ASC,
    voucher_no ASC;

END$$

CREATE DEFINER=`nrberp25`@`localhost` PROCEDURE `sp_GetStockTransferDetailsByInvoice` (IN `invoiceNo` VARCHAR(50))   BEGIN
    SELECT
    	s.id AS stock_id,
        s.stock_date AS stock_date,
        s.invoice_no AS invoice_no,
        s.warehouse_id AS from_warehouse_id,
        s.to_warehouse_id AS to_warehouse_id,
        s.product_id AS product_id,
        fw.name AS from_warehouse_name,
        tw.name AS to_warehouse_name,
        p.product_name AS product_name,
        s.stock_out_quantity AS quantity,
        s.stock_out_unit_price AS unit_price,
        s.stock_out_total_amount AS total_amount,
        s.status AS product_status
    FROM 
        stocks AS s
    JOIN products AS p ON s.product_id = p.id
    JOIN warehouses AS fw ON s.warehouse_id = fw.id
    JOIN warehouses AS tw ON s.to_warehouse_id = tw.id
    WHERE 
        s.invoice_no = invoiceNo;
END$$

CREATE DEFINER=`nrberp25`@`localhost` PROCEDURE `sp_GetStockTransferList` (IN `startDate` DATE, IN `endDate` DATE, IN `warehouse_id` INT, IN `status` INT)   BEGIN
    SELECT
        s.stock_date AS stock_date,
        s.invoice_no AS invoice_no,
        fw.name AS from_warehouse_name,
        tw.name AS to_warehouse_name,
        s.status AS status
    FROM 
        stocks AS s
    JOIN products AS p ON s.product_id = p.id
    JOIN warehouses AS fw ON s.warehouse_id = fw.id
    JOIN warehouses AS tw ON s.to_warehouse_id = tw.id
    WHERE 
        (s.warehouse_id = warehouse_id OR s.to_warehouse_id = warehouse_id OR warehouse_id = 0)
        AND s.stock_date BETWEEN startDate AND endDate
        AND s.invoice_no LIKE 'TRN%'
        AND s.status = status
    GROUP BY s.invoice_no;
END$$

