CREATE DEFINER=`nrberp25`@`localhost` PROCEDURE `sp_PendingServiceList` (IN `startDate` DATE, IN `endDate` DATE)   BEGIN
    WITH salesService AS (
        SELECT 
            psd.id as psd_id,
