CREATE DEFINER=`nrberp25`@`localhost` PROCEDURE `sp_SalesProfitInvoiceWise` (IN `startDate` DATE, IN `endDate` DATE)   BEGIN
    WITH sales AS (
        SELECT 
            st.invoice_no,
            DATE(MIN(st.stock_date)) AS sales_date,
            SUM(st.stock_out_quantity) AS quantity,
            ROUND(SUM(st.stock_out_quantity * st.purchase_price), 3) AS net_purchase_price,
            ROUND(SUM(st.stock_out_discount), 3) AS net_discount,
            ROUND(SUM(st.stock_out_total_amount), 3) AS net_sales_price,
            ROUND(SUM(st.stock_out_total_amount - (st.stock_out_quantity * st.purchase_price)), 3) AS net_profit
        FROM 
            stocks AS st
        JOIN 
            products AS p ON st.product_id = p.id
        WHERE 
            st.stock_date BETWEEN startDate AND endDate
            AND st.invoice_no LIKE 'INV%'
        GROUP BY 
            st.invoice_no
    )
    
    SELECT 
        invoice_no,
        sales_date,
        quantity,
        net_purchase_price,
        net_discount,
        net_sales_price,
        net_profit
    FROM 
        sales
    ORDER BY 
        invoice_no;
END$$

CREATE DEFINER=`nrberp25`@`localhost` PROCEDURE `sp_SalesProfitItemWise` (IN `startDate` DATE, IN `endDate` DATE, IN `givenProductID` INT)   BEGIN
    WITH avg_purchase AS (
        SELECT 
            st.product_id,
            ROUND(SUM(st.stock_in_total_amount) / NULLIF(SUM(st.stock_in_quantity), 0), 3) AS avg_purchase_price
        FROM 
            stocks AS st 
        WHERE 
            st.invoice_no LIKE 'PUR%'
        GROUP BY 
            st.product_id
    ),
    sales AS (
        SELECT 
            st.product_id,
            SUM(st.stock_out_quantity) AS total_sales_quantity,
            SUM(st.stock_out_total_amount) AS total_sales_amount
        FROM 
            stocks AS st
        WHERE 
            st.stock_date BETWEEN startDate AND endDate
            AND (st.product_id = givenProductID OR givenProductID = 0)
            AND st.invoice_no LIKE 'INV%'
        GROUP BY 
            st.product_id
    )
    
    SELECT 
        sa.product_id,
        p.product_name,
        sa.total_sales_quantity,
        ap.avg_purchase_price,
        ROUND((sa.total_sales_quantity * ap.avg_purchase_price), 3) AS total_purchase_amount,
        ROUND((sa.total_sales_amount / NULLIF(sa.total_sales_quantity, 0)), 3) AS avg_sales_price,
        ROUND(sa.total_sales_amount, 3) AS total_sales_amount,
        ROUND((sa.total_sales_amount - (sa.total_sales_quantity * ap.avg_purchase_price)), 3) AS total_profit
    FROM 
        sales AS sa
    JOIN 
        avg_purchase AS ap ON sa.product_id = ap.product_id
    JOIN 
        products AS p ON sa.product_id = p.id;
END$$

CREATE DEFINER=`nrberp25`@`localhost` PROCEDURE `sp_StockReportFinishGoodWise` (IN `CDate1` DATE, IN `CDate2` DATE, IN `CWarehouseId` INT, IN `CProductId` INT)   BEGIN
    -- Declare local variables
    DECLARE Date1 DATE;
    DECLARE Date2 DATE;
    DECLARE WarehouseId INT;
    DECLARE ProductId INT;

    -- Assign the procedure parameters to local variables
    SET Date1 = CDate1;
    SET Date2 = CDate2;
    SET WarehouseId = CWarehouseId;
    SET ProductId = CProductId;

    -- Main query to select product stock report with filtering
    SELECT
        products.id,
        products.product_name,
        products.unit_id,
        product_units.unit_name AS unit_name,
        IFNULL(warehouses.name, 'All Warehouse') AS warehouse_name,

        -- Get the most recent purchase price for each product
        (SELECT stocks.stock_in_unit_price
         FROM stocks 
         WHERE stocks.product_id = products.id
         ORDER BY stocks.stock_in_unit_price DESC 
         LIMIT 1) AS purchase_price,
        
        -- Calculate the pre-quantity (before Date1) for each warehouse
        IFNULL((
            SELECT
                ROUND(SUM(stocks.stock_in_quantity) - SUM(stocks.stock_out_quantity), 2)
            FROM
                stocks
            WHERE
                stocks.product_id = products.id
                AND (WarehouseId = 0 OR stocks.warehouse_id = WarehouseId)
                AND DATE(stocks.stock_date) BETWEEN '1900-01-01' AND DATE_SUB(Date1, INTERVAL 1 DAY)
        ), 0) AS PreQty,
        
        -- Calculate the stock-in quantity between Date1 and Date2
        IFNULL((
            SELECT
                ROUND(SUM(stocks.stock_in_quantity), 2)
            FROM
                stocks
            WHERE
                stocks.product_id = products.id
                AND (WarehouseId = 0 OR stocks.warehouse_id = WarehouseId)
                AND DATE(stocks.stock_date) BETWEEN Date1 AND Date2
        ), 0) AS InQty,
        
        -- Calculate the total stock quantity (PreQty + InQty)
        IFNULL((
            SELECT
                ROUND(SUM(stocks.stock_in_quantity) - SUM(stocks.stock_out_quantity), 2)
            FROM
                stocks
            WHERE
                stocks.product_id = products.id
                AND (WarehouseId = 0 OR stocks.warehouse_id = WarehouseId)
                AND DATE(stocks.stock_date) BETWEEN '1900-01-01' AND DATE_SUB(Date1, INTERVAL 1 DAY)
        ), 0) + IFNULL((
            SELECT
                ROUND(SUM(stocks.stock_in_quantity), 2)
            FROM
                stocks
            WHERE
                stocks.product_id = products.id
                AND (WarehouseId = 0 OR stocks.warehouse_id = WarehouseId)
                AND DATE(stocks.stock_date) BETWEEN Date1 AND Date2
        ), 0) AS TotQty,
        
        -- Calculate the stock-out quantity between Date1 and Date2
        IFNULL((
            SELECT
                ROUND(SUM(stocks.stock_out_quantity), 2)
            FROM
                stocks
            WHERE
                stocks.product_id = products.id
                AND (WarehouseId = 0 OR stocks.warehouse_id = WarehouseId)
                AND DATE(stocks.stock_date) BETWEEN Date1 AND Date2
        ), 0) AS OutQty
    FROM
        products
    INNER JOIN stocks ON products.id = stocks.product_id
    INNER JOIN product_units ON product_units.id = products.unit_id
    INNER JOIN warehouses ON stocks.warehouse_id = warehouses.id
    WHERE
        products.type_id = 1
        AND products.status = 1
        AND (ProductId = 0 OR products.id = ProductId)
        AND (WarehouseId = 0 OR stocks.warehouse_id = WarehouseId)
    GROUP BY
        products.id,
        products.product_name,
        products.unit_id,
        warehouses.id,
        warehouses.name
    ORDER BY
        products.id;

END$$

CREATE DEFINER=`nrberp25`@`localhost` PROCEDURE `sp_StockReportItemWise` (IN `CDate1` DATE, IN `CDate2` DATE, IN `CProductID` INT)   BEGIN

    SET @Date1 = CDate1;
    SET @Date2 = CDate2;
    SET @ProductID = CProductID;

    -- Temporary table to store opening balance
    CREATE TEMPORARY TABLE temp_opening_balance AS
    SELECT
        products.id AS product_id,
        IFNULL(SUM(stocks.stock_in_quantity), 0) AS OpeningInQty,
        IFNULL(SUM(stocks.stock_out_quantity), 0) AS OpeningOutQty
    FROM
        products
    LEFT JOIN stocks ON products.id = stocks.product_id
    WHERE
        products.id = @ProductID
        AND date(stocks.stock_date) < @Date1
    GROUP BY
        products.id;

    -- First part: Opening balance
    SELECT
        NULL AS product_id,
        NULL AS product_name,
        NULL AS unit_id,
        NULL AS unit_name,
        NULL AS invoice_no,
        NULL AS stock_date,
        NULL AS InQty,
        NULL AS OutQty,
        IFNULL((
            SELECT
                OpeningInQty - OpeningOutQty
            FROM
                temp_opening_balance
        ), 0) AS OpeningBalance
    UNION ALL
    -- Second part: Current period data
    SELECT
        products.id AS product_id,
        products.product_name,
        products.unit_id,
        product_units.unit_name AS unit_name,
        stocks.invoice_no,
        stocks.stock_date,
        IFNULL(SUM(stocks.stock_in_quantity), 0) AS InQty,
        IFNULL(SUM(stocks.stock_out_quantity), 0) AS OutQty,
        NULL AS OpeningBalance
    FROM
        products
    LEFT JOIN stocks ON products.id = stocks.product_id
    LEFT JOIN product_units ON product_units.id = products.unit_id
    WHERE
        products.id = @ProductID
        AND date(stocks.stock_date) BETWEEN @Date1 AND @Date2
    GROUP BY
        products.id,
        products.product_name,
        products.unit_id,
        product_units.unit_name,
        stocks.invoice_no,
        stocks.stock_date

    -- Ensure the entire result set is ordered by stock_date
    ORDER BY
        stock_date;

    -- Drop the temporary table after use
    DROP TEMPORARY TABLE IF EXISTS temp_opening_balance;

END$$

CREATE DEFINER=`nrberp25`@`localhost` PROCEDURE `sp_StockReportMaterialWise` (IN `CDate1` DATE, IN `CDate2` DATE, IN `CWarehouseId` INT, IN `CProductId` INT)   BEGIN
    -- Declare local variables
    DECLARE Date1 DATE;
    DECLARE Date2 DATE;
    DECLARE WarehouseId INT;
    DECLARE ProductId INT;

    -- Assign the procedure parameters to local variables
    SET Date1 = CDate1;
    SET Date2 = CDate2;
    SET WarehouseId = CWarehouseId;
    SET ProductId = CProductId;

    -- Main query to select product stock report with filtering
    SELECT
        products.id,
        products.product_name,
        products.unit_id,
        product_units.unit_name AS unit_name,
        warehouses.name AS warehouse_name,
        
         -- Get the most recent purchase price for each product
        (SELECT stocks.stock_in_unit_price
         FROM stocks 
         WHERE stocks.product_id = products.id
         ORDER BY stocks.stock_in_unit_price DESC 
         LIMIT 1) AS purchase_price,
        
        -- Calculate the pre-quantity (before Date1) for each warehouse
        IFNULL((SELECT ROUND(SUM(stocks.stock_in_quantity) - SUM(stocks.stock_out_quantity), 2)
                FROM stocks
                WHERE stocks.product_id = products.id
                AND (WarehouseId = 0 OR stocks.warehouse_id = WarehouseId)
                AND DATE(stocks.stock_date) BETWEEN '1900-01-01' AND DATE_SUB(Date1, INTERVAL 1 DAY)
        ), 0) AS PreQty,

        -- Calculate the stock-in quantity between Date1 and Date2
        IFNULL((SELECT ROUND(SUM(stocks.stock_in_quantity), 2)
                FROM stocks
                WHERE stocks.product_id = products.id
                AND (WarehouseId = 0 OR stocks.warehouse_id = WarehouseId)
                AND DATE(stocks.stock_date) BETWEEN Date1 AND Date2
        ), 0) AS InQty,

        -- Calculate the total stock quantity (PreQty + InQty)
        IFNULL((SELECT ROUND(SUM(stocks.stock_in_quantity) - SUM(stocks.stock_out_quantity), 2)
                FROM stocks
                WHERE stocks.product_id = products.id
                AND (WarehouseId = 0 OR stocks.warehouse_id = WarehouseId)
                AND DATE(stocks.stock_date) BETWEEN '1900-01-01' AND DATE_SUB(Date1, INTERVAL 1 DAY)
        ), 0) + IFNULL((SELECT ROUND(SUM(stocks.stock_in_quantity), 2)
                        FROM stocks
                        WHERE stocks.product_id = products.id
                        AND (WarehouseId = 0 OR stocks.warehouse_id = WarehouseId)
                        AND DATE(stocks.stock_date) BETWEEN Date1 AND Date2
        ), 0) AS TotQty,

        -- Calculate the stock-out quantity between Date1 and Date2
        IFNULL((SELECT ROUND(SUM(stocks.stock_out_quantity), 2)
                FROM stocks
                WHERE stocks.product_id = products.id
                AND (WarehouseId = 0 OR stocks.warehouse_id = WarehouseId)
                AND DATE(stocks.stock_date) BETWEEN Date1 AND Date2
        ), 0) AS OutQty

    FROM
        products
    INNER JOIN stocks ON products.id = stocks.product_id
    INNER JOIN product_units ON product_units.id = products.unit_id
    INNER JOIN warehouses ON stocks.warehouse_id = warehouses.id
    WHERE
        products.type_id = 2
        AND products.status = 1
        AND (ProductId = 0 OR products.id = ProductId)
        AND (WarehouseId = 0 OR stocks.warehouse_id = WarehouseId)
    GROUP BY
        products.id,
        products.product_name,
        products.unit_id,
        warehouses.id,
        warehouses.name
    ORDER BY
        products.id;
END$$

CREATE DEFINER=`nrberp25`@`localhost` PROCEDURE `sp_TotalProfit` (IN `startDate` DATE, IN `endDate` DATE)   BEGIN
SELECT 
    id,
    stock_date,
    stock_type,
    invoice_no,
    purchase_price,
    stock_out_quantity,
    stock_out_unit_price,
    FORMAT((purchase_price * stock_out_quantity), 2) AS purchase_sub_total,
    stock_out_total_amount AS stock_out_sub_total_amount,
    FORMAT((stock_out_total_amount - (purchase_price * stock_out_quantity)), 2) AS profit,    
    (SELECT FORMAT(SUM((purchase_price * stock_out_quantity)), 2) 
     FROM stocks WHERE stock_type = 'Out' AND stock_date BETWEEN startDate AND endDate) AS total_purchase,
     (SELECT FORMAT(SUM((stock_out_total_amount)), 2) 
     FROM stocks WHERE stock_type = 'Out' AND stock_date BETWEEN startDate AND endDate) AS total_sale,
    (SELECT FORMAT(SUM(stock_out_total_amount - (purchase_price * stock_out_quantity)), 2) 
     FROM stocks WHERE stock_type = 'Out' AND stock_date BETWEEN startDate AND endDate) AS total_profit
FROM 
    stocks 
WHERE 
    stock_type = 'Out' AND stock_date BETWEEN startDate AND endDate
ORDER BY `stocks`.`invoice_no` DESC;
END$$

CREATE DEFINER=`nrberp25`@`localhost` PROCEDURE `__sp_GetTotalSummeryReport` (IN `startDate` DATE, IN `endDate` DATE)   SELECT 
    FORMAT(IFNULL(SUM(s.stock_in_total_amount), 0.00), 2) AS total_purchase_amount,
    FORMAT(IFNULL(SUM(s.stock_out_total_amount), 0.00), 2) AS total_sales_amount,
    FORMAT(
        IFNULL(
            (SELECT SUM(ft.amount) 
             FROM finance_accounts fa
             JOIN finance_transactions ft ON fa.id = ft.acid 
             WHERE fa.account_group_code LIKE '2%' 
               AND fa.id != 13 
               AND ft.voucher_date BETWEEN startDate AND endDate),
            0.00
        ), 2
    ) AS total_expense_amount,
    FORMAT(
        IFNULL(
            (SELECT SUM(TotalValue)
             FROM (
                 SELECT
                    product_id, 
                    stock_in_unit_price AS Price, 
                    (SUM(CASE WHEN stock_date BETWEEN '1900' AND endDate THEN stock_in_quantity ELSE 0 END) 
                     - SUM(CASE WHEN stock_date BETWEEN '1900' AND endDate THEN stock_out_quantity ELSE 0 END)) AS Qty, 
                    (stock_in_unit_price * 
                     (SUM(CASE WHEN stock_date BETWEEN '1900' AND endDate THEN stock_in_quantity ELSE 0 END) 
                      - SUM(CASE WHEN stock_date BETWEEN '1900' AND endDate THEN stock_out_quantity ELSE 0 END))) AS TotalValue
                 FROM stocks
                 GROUP BY product_id, stock_in_unit_price
             ) AS ProductTotals
            ), 0.00
        ), 2
    ) AS current_stock_amount
FROM stocks AS s
WHERE s.stock_date BETWEEN startDate AND endDate$$

CREATE DEFINER=`nrberp25`@`localhost` PROCEDURE `__sp_StockReportFinishGoodWise` (IN `CDate1` DATE, IN `CDate2` DATE, IN `CWarehouseId` INT, IN `CProductId` INT)   BEGIN
    -- Declare local variables
    DECLARE Date1 DATE;
    DECLARE Date2 DATE;
    DECLARE WarehouseId INT;
    DECLARE ProductId INT;

    -- Assign the procedure parameters to local variables
    SET Date1 = CDate1;
    SET Date2 = CDate2;
    SET WarehouseId = CWarehouseId;
    SET ProductId = CProductId;

    -- Main query to select product stock report with filtering
    SELECT
        products.id,
        products.product_name,
        products.unit_id,
        product_units.unit_name AS unit_name,
        IFNULL(warehouses.name, 'No Warehouse') AS warehouse_name,

        -- Get the most recent purchase price for each product
        (SELECT stocks.stock_in_unit_price
         FROM stocks 
         WHERE stocks.product_id = products.id
         ORDER BY stocks.stock_in_unit_price DESC 
         LIMIT 1) AS purchase_price,
        
        -- Calculate the pre-quantity (before Date1) for each warehouse
        IFNULL((
            SELECT
                ROUND(SUM(stocks.stock_in_quantity) - SUM(stocks.stock_out_quantity), 2)
            FROM
                stocks
            WHERE
                stocks.product_id = products.id
                AND (WarehouseId = 0 OR stocks.warehouse_id = WarehouseId)
                AND stocks.warehouse_id = warehouses.id -- Ensure it's specific to the warehouse
                AND DATE(stocks.stock_date) BETWEEN '1900-01-01' AND DATE_SUB(Date1, INTERVAL 1 DAY)
        ), 0) AS PreQty,
        
        -- Calculate the stock-in quantity between Date1 and Date2
        IFNULL((
            SELECT
                ROUND(SUM(stocks.stock_in_quantity), 2)
            FROM
                stocks
            WHERE
                stocks.product_id = products.id
                AND (WarehouseId = 0 OR stocks.warehouse_id = WarehouseId)
                AND stocks.warehouse_id = warehouses.id -- Ensure it's specific to the warehouse
                AND DATE(stocks.stock_date) BETWEEN Date1 AND Date2
        ), 0) AS InQty,
        
        -- Calculate the total stock quantity (PreQty + InQty)
        IFNULL((
            SELECT
                ROUND(SUM(stocks.stock_in_quantity) - SUM(stocks.stock_out_quantity), 2)
            FROM
                stocks
            WHERE
                stocks.product_id = products.id
                AND (WarehouseId = 0 OR stocks.warehouse_id = WarehouseId)
                AND stocks.warehouse_id = warehouses.id -- Ensure it's specific to the warehouse
                AND DATE(stocks.stock_date) BETWEEN '1900-01-01' AND DATE_SUB(Date1, INTERVAL 1 DAY)
        ), 0) + IFNULL((
            SELECT
                ROUND(SUM(stocks.stock_in_quantity), 2)
            FROM
                stocks
            WHERE
                stocks.product_id = products.id
                AND (WarehouseId = 0 OR stocks.warehouse_id = WarehouseId)
                AND stocks.warehouse_id = warehouses.id -- Ensure it's specific to the warehouse
                AND DATE(stocks.stock_date) BETWEEN Date1 AND Date2
        ), 0) AS TotQty,
        
        -- Calculate the stock-out quantity between Date1 and Date2
        IFNULL((
            SELECT
                ROUND(SUM(stocks.stock_out_quantity), 2)
            FROM
                stocks
            WHERE
                stocks.product_id = products.id
                AND (WarehouseId = 0 OR stocks.warehouse_id = WarehouseId)
                AND stocks.warehouse_id = warehouses.id -- Ensure it's specific to the warehouse
                AND DATE(stocks.stock_date) BETWEEN Date1 AND Date2
        ), 0) AS OutQty
    FROM
        products
    LEFT JOIN stocks ON products.id = stocks.product_id
    LEFT JOIN product_units ON product_units.id = products.unit_id
    LEFT JOIN warehouses ON stocks.warehouse_id = warehouses.id
    WHERE
        products.type_id = 1
        AND products.status = 1
        AND (ProductId = 0 OR products.id = ProductId)
        AND (WarehouseId = 0 OR stocks.warehouse_id = WarehouseId)
    GROUP BY
        products.id,
        products.product_name,
        products.unit_id,
        warehouses.id,
        warehouses.name
    ORDER BY
        products.id;

END$$

CREATE DEFINER=`nrberp25`@`localhost` PROCEDURE `__sp_StockReportItemWise` (IN `CDate1` DATE, IN `CDate2` DATE, IN `CProductID` INT)   BEGIN

    SET @Date1 = CDate1;
    SET @Date2 = CDate2;
    SET @ProductID = CProductID;

    -- Temporary table to store opening balance
    CREATE TEMPORARY TABLE temp_opening_balance AS
    SELECT
        products.id AS product_id,
        IFNULL(SUM(stocks.stock_in_quantity), 0) AS OpeningInQty,
        IFNULL(SUM(stocks.stock_out_quantity), 0) AS OpeningOutQty
    FROM
        products
    LEFT JOIN stocks ON products.id = stocks.product_id
    WHERE
        products.id = @ProductID
        AND date(stocks.stock_date) < @Date1
    GROUP BY
        products.id;

    -- First part: Opening balance
    SELECT
        NULL AS product_id,
        NULL AS product_name,
        NULL AS unit_id,
        NULL AS unit_name,
        NULL AS invoice_no,
        NULL AS stock_date,
        NULL AS InQty,
        NULL AS OutQty,
        IFNULL((
            SELECT
                OpeningInQty - OpeningOutQty
            FROM
                temp_opening_balance
        ), 0) AS OpeningBalance
    UNION ALL
    -- Second part: Current period data
    SELECT
        products.id AS product_id,
        products.product_name,
        products.unit_id,
        product_units.unit_name AS unit_name,
        stocks.invoice_no,
        stocks.stock_date,
        IFNULL(SUM(stocks.stock_in_quantity), 0) AS InQty,
        IFNULL(SUM(stocks.stock_out_quantity), 0) AS OutQty,
        NULL AS OpeningBalance
    FROM
        products
    LEFT JOIN stocks ON products.id = stocks.product_id
    LEFT JOIN product_units ON product_units.id = products.unit_id
    WHERE
        products.id = @ProductID
        AND date(stocks.stock_date) BETWEEN @Date1 AND @Date2
    GROUP BY
        products.id,
        products.product_name,
        products.unit_id,
        product_units.unit_name,
        stocks.invoice_no,
        stocks.stock_date

    -- Ensure the entire result set is ordered by stock_date
    ORDER BY
        stock_date;

    -- Drop the temporary table after use
    DROP TEMPORARY TABLE IF EXISTS temp_opening_balance;

END$$

